#include <stdio.h>
struct DNode { int data; struct DNode *prev, *next; };
int main(void) {
    struct DNode b = {2, 0, 0}, a = {1, 0, &b};
    b.prev = &a;
    printf("%d %d\n", a.next->data, b.prev->data);
    return 0;
}

#include <stdio.h>
struct Node { int data; struct Node *next; };
int main(void) {
    struct Node c = {3, 0}, b = {2, &c}, a = {1, &b};
    c.next = &a;
    struct Node *p = &a;
    for (int k = 0; k < 5; k++) { printf("%d", p->data); p = p->next; }
    return 0;
}

