#include <stdio.h>
struct Node { int data; struct Node *next; };
int main(void) {
    struct Node c = {3, 0}, b = {2, &c}, a = {1, &b};
    c.next = &a;
    int n = 0;
    struct Node *p = &a;
    do { n++; p = p->next; } while (p != &a);
    printf("%d\n", n);
    return 0;
}

