#include <stdio.h>
struct DNode { int data; struct DNode *prev, *next; };
int main(void) {
    struct DNode c = {3, 0, 0}, b = {2, 0, &c}, a = {1, 0, &b};
    b.prev = &a; c.prev = &b;
    struct DNode *head = &a;
    head->next->prev = 0; head = head->next;
    printf("%d %d\n", head->data, head->prev == 0);
    return 0;
}
